7	import type { MCPServerConfig } from '../../config/config.js';
8	
9	/**
10	 * Applies the admin allowlist to the local MCP servers.
11	 *
12	 * If an admin allowlist is provided and not empty, this function filters the
13	 * local servers to only those present in the allowlist. It also overrides
14	 * connection details (url, type, trust) with the admin configuration and
15	 * removes local execution details (command, args, env, cwd).
16	 *
17	 * @param localMcpServers The locally configured MCP servers.
18	 * @param adminAllowlist The admin allowlist configuration.
19	 * @returns The filtered and merged MCP servers.
20	 */
21	export function applyAdminAllowlist(
22	  localMcpServers: Record<string, MCPServerConfig>,
23	  adminAllowlist: Record<string, MCPServerConfig> | undefined,
24	): {
25	  mcpServers: Record<string, MCPServerConfig>;
26	  blockedServerNames: string[];
27	} {
28	  if (!adminAllowlist || Object.keys(adminAllowlist).length === 0) {
29	    return { mcpServers: localMcpServers, blockedServerNames: [] };
30	  }
31	
32	  const filteredMcpServers: Record<string, MCPServerConfig> = {};
33	  const blockedServerNames: string[] = [];
34	
35	  for (const [serverId, localConfig] of Object.entries(localMcpServers)) {
36	    const adminConfig = adminAllowlist[serverId];
37	    if (adminConfig) {
38	      const mergedConfig = {
39	        ...localConfig,
40	        url: adminConfig.url,
41	        type: adminConfig.type,
42	        trust: adminConfig.trust,
43	      };
44	
45	      // Remove local connection details
46	      delete mergedConfig.command;
47	      delete mergedConfig.args;
48	      delete mergedConfig.env;
49	      delete mergedConfig.cwd;
50	      delete mergedConfig.httpUrl;
51	      delete mergedConfig.tcp;
52	
53	      if (
54	        (adminConfig.includeTools && adminConfig.includeTools.length > 0) ||
55	        (adminConfig.excludeTools && adminConfig.excludeTools.length > 0)
56	      ) {
57	        mergedConfig.includeTools = adminConfig.includeTools;
58	        mergedConfig.excludeTools = adminConfig.excludeTools;
59	      }
60	
61	      filteredMcpServers[serverId] = mergedConfig;
62	    } else {
63	      blockedServerNames.push(serverId);
64	    }
65	  }
66	  return { mcpServers: filteredMcpServers, blockedServerNames };
67	}
