7	import type { CodeAssistServer } from '../server.js';
8	import { debugLogger } from '../../utils/debugLogger.js';
9	import { isDeepStrictEqual } from 'node:util';
10	import {
11	  type FetchAdminControlsResponse,
12	  FetchAdminControlsResponseSchema,
13	  McpConfigDefinitionSchema,
14	  type AdminControlsSettings,
15	} from '../types.js';
16	import { getCodeAssistServer } from '../codeAssist.js';
17	import type { Config } from '../../config/config.js';
18	
19	let pollingInterval: NodeJS.Timeout | undefined;
20	let currentSettings: AdminControlsSettings | undefined;
21	
22	export function sanitizeAdminSettings(
23	  settings: FetchAdminControlsResponse,
24	): AdminControlsSettings {
25	  const result = FetchAdminControlsResponseSchema.safeParse(settings);
26	  if (!result.success) {
27	    return {};
28	  }
29	  const sanitized = result.data;
30	  let mcpConfig;
31	
32	  if (sanitized.mcpSetting?.mcpConfigJson) {
33	    try {
34	      // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment
35	      const parsed = JSON.parse(sanitized.mcpSetting.mcpConfigJson);
36	      const validationResult = McpConfigDefinitionSchema.safeParse(parsed);
37	
38	      if (validationResult.success) {
39	        mcpConfig = validationResult.data;
40	        // Sort include/exclude tools for stable comparison
41	        if (mcpConfig.mcpServers) {
42	          for (const server of Object.values(mcpConfig.mcpServers)) {
43	            if (server.includeTools) {
44	              server.includeTools.sort();
45	            }
46	            if (server.excludeTools) {
47	              server.excludeTools.sort();
48	            }
49	          }
50	        }
51	      }
52	    } catch (_e) {
53	      // Ignore parsing errors
54	    }
55	  }
56	
57	  // Apply defaults (secureModeEnabled is supported for backward compatibility)
58	  let strictModeDisabled = false;
59	  if (sanitized.strictModeDisabled !== undefined) {
60	    strictModeDisabled = sanitized.strictModeDisabled;
61	  } else if (sanitized.secureModeEnabled !== undefined) {
62	    strictModeDisabled = !sanitized.secureModeEnabled;
63	  }
64	
65	  return {
66	    strictModeDisabled,
67	    cliFeatureSetting: {
68	      ...sanitized.cliFeatureSetting,
69	      extensionsSetting: {
70	        extensionsEnabled:
71	          sanitized.cliFeatureSetting?.extensionsSetting?.extensionsEnabled ??
72	          false,
73	      },
74	      unmanagedCapabilitiesEnabled:
75	        sanitized.cliFeatureSetting?.unmanagedCapabilitiesEnabled ?? false,
76	    },
77	    mcpSetting: {
78	      mcpEnabled: sanitized.mcpSetting?.mcpEnabled ?? false,
79	      mcpConfig: mcpConfig ?? {},
80	    },
81	  };
82	}
