84	/**
85	 * Fetches the admin controls from the server if enabled by experiment flag.
86	 * Safely handles polling start/stop based on the flag and server availability.
87	 *
88	 * @param server The CodeAssistServer instance.
89	 * @param cachedSettings The cached settings to use if available.
90	 * @param adminControlsEnabled Whether admin controls are enabled.
91	 * @param onSettingsChanged Callback to invoke when settings change during polling.
92	 * @returns The fetched settings if enabled and successful, otherwise undefined.
93	 */
94	export async function fetchAdminControls(
95	  server: CodeAssistServer | undefined,
96	  cachedSettings: AdminControlsSettings | undefined,
97	  adminControlsEnabled: boolean,
98	  onSettingsChanged: (settings: AdminControlsSettings) => void,
99	): Promise<AdminControlsSettings> {
100	  if (!server || !server.projectId || !adminControlsEnabled) {
101	    stopAdminControlsPolling();
102	    currentSettings = undefined;
103	    return {};
104	  }
105	
106	  // If we already have settings (e.g. from IPC during relaunch), use them
107	  // to avoid blocking startup with another fetch. We'll still start polling.
108	  if (cachedSettings && Object.keys(cachedSettings).length !== 0) {
109	    currentSettings = cachedSettings;
110	    startAdminControlsPolling(server, server.projectId, onSettingsChanged);
111	    return cachedSettings;
112	  }
113	
114	  try {
115	    const rawSettings = await server.fetchAdminControls({
116	      project: server.projectId,
117	    });
118	
119	    if (rawSettings.adminControlsApplicable !== true) {
120	      stopAdminControlsPolling();
121	      currentSettings = undefined;
122	      return {};
123	    }
124	
125	    const sanitizedSettings = sanitizeAdminSettings(rawSettings);
126	    currentSettings = sanitizedSettings;
127	    startAdminControlsPolling(server, server.projectId, onSettingsChanged);
128	    return sanitizedSettings;
129	  } catch (e) {
130	    debugLogger.error('Failed to fetch admin controls: ', e);
131	    throw e;
132	  }
133	}
134	
135	/**
136	 * Fetches the admin controls from the server a single time.
137	 * This function does not start or stop any polling.
138	 *
139	 * @param server The CodeAssistServer instance.
140	 * @param adminControlsEnabled Whether admin controls are enabled.
141	 * @returns The fetched settings if enabled and successful, otherwise undefined.
142	 */
143	export async function fetchAdminControlsOnce(
144	  server: CodeAssistServer | undefined,
145	  adminControlsEnabled: boolean,
146	): Promise<FetchAdminControlsResponse> {
147	  if (!server || !server.projectId || !adminControlsEnabled) {
148	    return {};
149	  }
150	
151	  try {
152	    const rawSettings = await server.fetchAdminControls({
153	      project: server.projectId,
154	    });
155	
156	    if (rawSettings.adminControlsApplicable !== true) {
157	      return {};
158	    }
159	
160	    return sanitizeAdminSettings(rawSettings);
161	  } catch (e) {
162	    debugLogger.error(
163	      'Failed to fetch admin controls: ',
164	      e instanceof Error ? e.message : e,
165	    );
166	    throw e;
167	  }
168	}
169	
170	/**
171	 * Starts polling for admin controls.
172	 */
173	function startAdminControlsPolling(
174	  server: CodeAssistServer,
175	  project: string,
176	  onSettingsChanged: (settings: AdminControlsSettings) => void,
177	) {
178	  stopAdminControlsPolling();
179	
180	  pollingInterval = setInterval(
181	    async () => {
182	      try {
183	        const rawSettings = await server.fetchAdminControls({
184	          project,
185	        });
186	
187	        if (rawSettings.adminControlsApplicable !== true) {
188	          stopAdminControlsPolling();
189	          currentSettings = undefined;
190	          return;
191	        }
192	
193	        const newSettings = sanitizeAdminSettings(rawSettings);
194	
195	        if (!isDeepStrictEqual(newSettings, currentSettings)) {
196	          currentSettings = newSettings;
197	          onSettingsChanged(newSettings);
198	        }
199	      } catch (e) {
200	        debugLogger.error('Failed to poll admin controls: ', e);
201	      }
202	    },
203	    5 * 60 * 1000,
204	  ); // 5 minutes
205	}
206	
207	/**
208	 * Stops polling for admin controls.
209	 */
210	export function stopAdminControlsPolling() {
211	  if (pollingInterval) {
212	    clearInterval(pollingInterval);
213	    pollingInterval = undefined;
214	  }
215	}
