217	/**
218	 * Returns a standardized error message for features disabled by admin settings.
219	 *
220	 * @param featureName The name of the disabled feature
221	 * @param config The application config
222	 * @returns The formatted error message
223	 */
224	export function getAdminErrorMessage(
225	  featureName: string,
226	  config: Config | undefined,
227	): string {
228	  const server = config ? getCodeAssistServer(config) : undefined;
229	  const projectId = server?.projectId;
230	  const projectParam = projectId ? `?project=${projectId}` : '';
231	  return `${featureName} is disabled by your administrator. To enable it, please request an update to the settings at: https://goo.gle/manage-gemini-cli${projectParam}`;
232	}
