7	import { describe, it, expect } from 'vitest';
8	import { applyAdminAllowlist } from './mcpUtils.js';
9	import type { MCPServerConfig } from '../../config/config.js';
10	
11	describe('applyAdminAllowlist', () => {
12	  it('should return original servers if no allowlist provided', () => {
13	    const localServers: Record<string, MCPServerConfig> = {
14	      server1: { command: 'cmd1' },
15	    };
16	    expect(applyAdminAllowlist(localServers, undefined)).toEqual({
17	      mcpServers: localServers,
18	      blockedServerNames: [],
19	    });
20	  });
21	
22	  it('should return original servers if allowlist is empty', () => {
23	    const localServers: Record<string, MCPServerConfig> = {
24	      server1: { command: 'cmd1' },
25	    };
26	    expect(applyAdminAllowlist(localServers, {})).toEqual({
27	      mcpServers: localServers,
28	      blockedServerNames: [],
29	    });
30	  });
31	
32	  it('should filter servers not in allowlist', () => {
33	    const localServers: Record<string, MCPServerConfig> = {
34	      server1: { command: 'cmd1' },
35	      server2: { command: 'cmd2' },
36	    };
37	    const allowlist: Record<string, MCPServerConfig> = {
38	      server1: { url: 'http://server1' },
39	    };
40	
41	    const result = applyAdminAllowlist(localServers, allowlist);
42	    expect(Object.keys(result.mcpServers)).toEqual(['server1']);
43	    expect(result.blockedServerNames).toEqual(['server2']);
44	  });
45	
46	  it('should override connection details with allowlist values', () => {
47	    const localServers: Record<string, MCPServerConfig> = {
48	      server1: {
49	        command: 'local-cmd',
50	        args: ['local-arg'],
51	        env: { LOCAL: 'true' },
52	        description: 'Local description',
53	      },
54	    };
55	    const allowlist: Record<string, MCPServerConfig> = {
56	      server1: {
57	        url: 'http://admin-url',
58	        type: 'sse',
59	        trust: true,
60	      },
61	    };
62	
63	    const result = applyAdminAllowlist(localServers, allowlist);
64	    const server = result.mcpServers['server1'];
65	
66	    expect(server).toBeDefined();
67	    expect(server?.url).toBe('http://admin-url');
68	    expect(server?.type).toBe('sse');
69	    expect(server?.trust).toBe(true);
70	    // Should preserve other local fields
71	    expect(server?.description).toBe('Local description');
72	    // Should remove local connection fields
73	    expect(server?.command).toBeUndefined();
74	    expect(server?.args).toBeUndefined();
75	    expect(server?.env).toBeUndefined();
76	  });
77	
78	  it('should apply tool restrictions from allowlist', () => {
79	    const localServers: Record<string, MCPServerConfig> = {
80	      server1: { command: 'cmd1' },
81	    };
