33	export async function getMcpServersFromConfig(
34	  settings?: MergedSettings,
35	): Promise<{
36	  mcpServers: Record<string, MCPServerConfig>;
37	  blockedServerNames: string[];
38	}> {
39	  if (!settings) {
40	    settings = loadSettings().merged;
41	  }
42	
43	  const extensionManager = new ExtensionManager({
44	    settings,
45	    workspaceDir: process.cwd(),
46	    requestConsent: requestConsentNonInteractive,
47	    requestSetting: promptForSetting,
48	  });
49	  const extensions = await extensionManager.loadExtensions();
50	  const mcpServers = { ...settings.mcpServers };
51	  for (const extension of extensions) {
52	    Object.entries(extension.mcpServers || {}).forEach(([key, server]) => {
53	      if (mcpServers[key]) {
54	        return;
55	      }
56	      mcpServers[key] = {
57	        ...server,
58	        extension,
59	      };
60	    });
61	  }
62	
63	  const adminAllowlist = settings.admin?.mcp?.config;
64	  const filteredResult = applyAdminAllowlist(mcpServers, adminAllowlist);
65	
66	  return filteredResult;
67	}
