69	async function testMCPConnection(
70	  serverName: string,
71	  config: MCPServerConfig,
72	  isTrusted: boolean,
73	  activeSettings: MergedSettings,
74	): Promise<MCPServerStatus> {
75	  // SECURITY: Only test connection if workspace is trusted or if it's a remote server.
76	  // stdio servers execute local commands and must never run in untrusted workspaces.
77	  const isStdio = !!config.command;
78	  if (isStdio && !isTrusted) {
79	    return MCPServerStatus.DISCONNECTED;
80	  }
81	
82	  const client = new Client({
83	    name: 'mcp-test-client',
84	    version: '0.0.1',
85	  });
86	
87	  const mcpContext = {
88	    sanitizationConfig: {
89	      enableEnvironmentVariableRedaction: true,
90	      allowedEnvironmentVariables: [],
91	      blockedEnvironmentVariables: activeSettings.advanced.excludedEnvVars,
92	    },
93	    emitMcpDiagnostic: (
94	      severity: 'info' | 'warning' | 'error',
95	      message: string,
96	      error?: unknown,
97	      serverName?: string,
98	    ) => {
99	      // In non-interactive list, we log everything through debugLogger for consistency
100	      if (severity === 'error') {
101	        debugLogger.error(
102	          chalk.red(`Error${serverName ? ` (${serverName})` : ''}: ${message}`),
103	          error,
104	        );
105	      } else if (severity === 'warning') {
106	        debugLogger.warn(
107	          chalk.yellow(
108	            `Warning${serverName ? ` (${serverName})` : ''}: ${message}`,
109	          ),
110	          error,
111	        );
112	      } else {
113	        debugLogger.log(message, error);
114	      }
115	    },
116	    isTrustedFolder: () => isTrusted,
117	  };
118	
119	  let transport;
120	  try {
121	    // Use the same transport creation logic as core
122	    transport = await createTransport(serverName, config, false, mcpContext);
123	  } catch (_error) {
124	    await client.close();
125	    return MCPServerStatus.DISCONNECTED;
126	  }
127	
128	  try {
129	    // Attempt actual MCP connection with short timeout
130	    await client.connect(transport, { timeout: 5000 }); // 5s timeout
131	
132	    // Test basic MCP protocol by pinging the server
133	    await client.ping();
134	
135	    await client.close();
136	    return MCPServerStatus.CONNECTED;
137	  } catch (_error) {
138	    await transport.close();
139	    return MCPServerStatus.DISCONNECTED;
140	  }
141	}
