143	async function getServerStatus(
144	  serverName: string,
145	  server: MCPServerConfig,
146	  isTrusted: boolean,
147	  activeSettings: MergedSettings,
148	): Promise<MCPServerStatus> {
149	  const mcpEnablementManager = McpServerEnablementManager.getInstance();
150	  const loadResult = await canLoadServer(serverName, {
151	    adminMcpEnabled: activeSettings.admin?.mcp?.enabled ?? true,
152	    allowedList: activeSettings.mcp?.allowed,
153	    excludedList: activeSettings.mcp?.excluded,
154	    enablement: mcpEnablementManager.getEnablementCallbacks(),
155	  });
156	
157	  if (!loadResult.allowed) {
158	    if (
159	      loadResult.blockType === 'admin' ||
160	      loadResult.blockType === 'allowlist' ||
161	      loadResult.blockType === 'excludelist'
162	    ) {
163	      return MCPServerStatus.BLOCKED;
164	    }
165	    return MCPServerStatus.DISABLED;
166	  }
167	
168	  // Test all server types by attempting actual connection
169	  return testMCPConnection(serverName, server, isTrusted, activeSettings);
170	}
