496	function findEnvFile(startDir: string): string | null {
497	  let currentDir = path.resolve(startDir);
498	  while (true) {
499	    // prefer gemini-specific .env under GEMINI_DIR
500	    const geminiEnvPath = path.join(currentDir, GEMINI_DIR, '.env');
501	    if (fs.existsSync(geminiEnvPath)) {
502	      return geminiEnvPath;
503	    }
504	    const envPath = path.join(currentDir, '.env');
505	    if (fs.existsSync(envPath)) {
506	      return envPath;
507	    }
508	    const parentDir = path.dirname(currentDir);
509	    if (parentDir === currentDir || !parentDir) {
510	      // check .env under home as fallback, again preferring gemini-specific .env
511	      const homeGeminiEnvPath = path.join(homedir(), GEMINI_DIR, '.env');
512	      if (fs.existsSync(homeGeminiEnvPath)) {
513	        return homeGeminiEnvPath;
514	      }
515	      const homeEnvPath = path.join(homedir(), '.env');
516	      if (fs.existsSync(homeEnvPath)) {
517	        return homeEnvPath;
518	      }
519	      return null;
520	    }
521	    currentDir = parentDir;
522	  }
