7	import { MCPServerConfig } from '../../config/config.js';
8	import type { RequiredMcpServerConfig } from '../types.js';
9	
10	/**
11	 * Applies the admin allowlist to the local MCP servers.
12	 *
13	 * If an admin allowlist is provided and not empty, this function filters the
14	 * local servers to only those present in the allowlist. It also overrides
15	 * connection details (url, type, trust) with the admin configuration and
16	 * removes local execution details (command, args, env, cwd).
17	 *
18	 * @param localMcpServers The locally configured MCP servers.
19	 * @param adminAllowlist The admin allowlist configuration.
20	 * @returns The filtered and merged MCP servers.
21	 */
22	export function applyAdminAllowlist(
23	  localMcpServers: Record<string, MCPServerConfig>,
24	  adminAllowlist: Record<string, MCPServerConfig> | undefined,
25	): {
26	  mcpServers: Record<string, MCPServerConfig>;
27	  blockedServerNames: string[];
28	} {
29	  if (!adminAllowlist || Object.keys(adminAllowlist).length === 0) {
30	    return { mcpServers: localMcpServers, blockedServerNames: [] };
31	  }
32	
33	  const filteredMcpServers: Record<string, MCPServerConfig> = {};
34	  const blockedServerNames: string[] = [];
35	
36	  for (const [serverId, localConfig] of Object.entries(localMcpServers)) {
37	    const adminConfig = adminAllowlist[serverId];
38	    if (adminConfig) {
39	      const mergedConfig = {
40	        // eslint-disable-next-line @typescript-eslint/no-misused-spread
41	        ...localConfig,
42	        url: adminConfig.url,
43	        type: adminConfig.type,
44	        trust: adminConfig.trust,
45	      };
46	
47	      // Remove local connection details
48	      delete mergedConfig.command;
49	      delete mergedConfig.args;
50	      delete mergedConfig.env;
51	      delete mergedConfig.cwd;
52	      delete mergedConfig.httpUrl;
53	      delete mergedConfig.tcp;
54	
55	      if (
56	        (adminConfig.includeTools && adminConfig.includeTools.length > 0) ||
57	        (adminConfig.excludeTools && adminConfig.excludeTools.length > 0)
58	      ) {
59	        mergedConfig.includeTools = adminConfig.includeTools;
60	        mergedConfig.excludeTools = adminConfig.excludeTools;
61	      }
62	
63	      filteredMcpServers[serverId] = mergedConfig;
64	    } else {
65	      blockedServerNames.push(serverId);
66	    }
67	  }
68	  return { mcpServers: filteredMcpServers, blockedServerNames };
69	}
