71	/**
72	 * Applies admin-required MCP servers by injecting them into the MCP server
73	 * list. Required servers always take precedence over locally configured servers
74	 * with the same name and cannot be disabled by the user.
75	 *
76	 * @param mcpServers The current MCP servers (after allowlist filtering).
77	 * @param requiredServers The admin-required MCP server configurations.
78	 * @returns The MCP servers with required servers injected, and the list of
79	 *   required server names for informational purposes.
80	 */
81	export function applyRequiredServers(
82	  mcpServers: Record<string, MCPServerConfig>,
83	  requiredServers: Record<string, RequiredMcpServerConfig> | undefined,
84	): {
85	  mcpServers: Record<string, MCPServerConfig>;
86	  requiredServerNames: string[];
87	} {
88	  if (!requiredServers || Object.keys(requiredServers).length === 0) {
89	    return { mcpServers, requiredServerNames: [] };
90	  }
91	
92	  const result: Record<string, MCPServerConfig> = { ...mcpServers };
93	  const requiredServerNames: string[] = [];
94	
95	  for (const [serverId, requiredConfig] of Object.entries(requiredServers)) {
96	    requiredServerNames.push(serverId);
97	
98	    // Convert RequiredMcpServerConfig to MCPServerConfig.
99	    // Required servers completely override any local config with the same name.
100	    result[serverId] = new MCPServerConfig(
101	      undefined, // command (stdio not supported for required servers)
102	      undefined, // args
103	      undefined, // env
104	      undefined, // cwd
105	      requiredConfig.url, // url
106	      undefined, // httpUrl (use url + type instead)
107	      requiredConfig.headers, // headers
108	      undefined, // tcp
109	      requiredConfig.type, // type
110	      requiredConfig.timeout, // timeout
111	      requiredConfig.trust ?? true, // trust defaults to true for admin-forced
112	      requiredConfig.description, // description
113	      requiredConfig.includeTools, // includeTools
114	      requiredConfig.excludeTools, // excludeTools
115	      undefined, // extension
116	      requiredConfig.oauth, // oauth
117	      requiredConfig.authProviderType, // authProviderType
118	      requiredConfig.targetAudience, // targetAudience
119	      requiredConfig.targetServiceAccount, // targetServiceAccount
120	    );
121	  }
122	
123	  return { mcpServers: result, requiredServerNames };
124	}
